# region: gather
def gather(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: intake
def intake(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: emit
def emit(xs, factor=3):
    return [v * factor for v in xs]

# region: digest
def digest(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: render
def render(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n // bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return render(digest(emit(intake(gather(raw)))))

